#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long n = strtol(argv[1], &end1, 10);
    long m = strtol(argv[2], &end2, 10);
    // Validate first argument is a proper integer
    if (end1 == argv[1] || *end1 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    // Validate second argument is a proper integer
    if (end2 == argv[2] || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (m < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (m > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    double sum = 0.0;
    switch (n) {
        case 1: // sum of 1/(i*i)
            for (long i = 1; i <= m; ++i) {
                sum += 1.0 / ((double)i * (double)i);
            }
            break;
        case 2: // harmonic series sum 1/i
            for (long i = 1; i <= m; ++i) {
                sum += 1.0 / (double)i;
            }
            break;
        case 3: // sum of 1/i! (e approximation)
            sum = 1.0; // term for i = 0
            {
                double term = 1.0;
                for (long i = 1; i <= m; ++i) {
                    term /= (double)i; // term = 1/i!
                    sum += term;
                }
            }
            break;
        default:
            puts("BAD_MODE");
            return 0;
    }
    printf("%.6f\n", sum);
    return 0;
}
